// Fictional training scenario only; this is NOT a jurisdiction-specific rules engine.
export const STAGES=["Intake","Pleadings","Evidence","Hearing","Conclusion"];
export const ROLES=["judge","plaintiff","defendant","counsel_plaintiff","counsel_defendant","witness","clerk"];
export const EXHIBITS={contract:"Exhibit A • Fictional service agreement: Contractor agrees to repair three fixtures; payment is due following satisfactory completion.",invoice:"Exhibit B • Fictional invoice: $2,400 billed. The invoice itself does not prove completion or acceptance."};
export const OPTIONS=[
 [{id:"identify",label:"Identify the parties and disputed issue",roles:["judge","plaintiff","defendant","counsel_plaintiff","counsel_defendant","clerk"],reply:"The case has two opposing sides and a dispute about satisfactory performance."},{id:"observe",label:"Review the case summary",roles:ROLES,reply:"The provided facts are allegations to investigate, not established legal conclusions."}],
 [{id:"plaintiff_claim",label:"Explain the plaintiff's claim",roles:["plaintiff","counsel_plaintiff","judge"],reply:"Plaintiff alleges a contract, performance and a payment obligation."},{id:"defense",label:"Explain the defendant's response",roles:["defendant","counsel_defendant","judge"],reply:"Defendant disputes performance and asserts that payment is contested."},{id:"docket",label:"Record the parties' positions",roles:["clerk"],reply:"The positions are recorded in the fictional training docket."},{id:"observe",label:"Listen to the positions",roles:["witness"],reply:"Witnesses should avoid adopting either party's legal claims as facts."}],
 [{id:"offer_contract",label:"Offer the contract for review",roles:["plaintiff","counsel_plaintiff","defendant","counsel_defendant"],reply:"The contract is marked for discussion. Admission is not automatic."},{id:"offer_invoice",label:"Offer the invoice for review",roles:["plaintiff","counsel_plaintiff","defendant","counsel_defendant"],reply:"The invoice is marked for discussion. Its weight remains disputed."},{id:"evaluate",label:"Ask about relevance and foundation",roles:["judge"],reply:"A simulated judge asks for an explanation of relevance and how the document is authenticated."},{id:"testify",label:"Describe only what was personally observed",roles:["witness"],reply:"The witness describes observations, without guessing at unknown facts."},{id:"log",label:"Record evidence identification",roles:["clerk"],reply:"Fictional exhibit entries are added to the case log."}],
 [{id:"object",label:"Raise an objection and explain why",roles:["plaintiff","defendant","counsel_plaintiff","counsel_defendant"],reply:"An objection is noted. This demo does not pretend to resolve a legal evidence rule."},{id:"rule",label:"Request arguments before a training ruling",roles:["judge"],reply:"The court asks both sides for their positions before determining a fictional next step."},{id:"answer",label:"Answer the question without speculation",roles:["witness"],reply:"The witness limits testimony to what they know."},{id:"record",label:"Maintain the hearing transcript",roles:["clerk"],reply:"A timestamped hearing event is recorded in the transcript."}],
 [{id:"reflect",label:"Review the strongest evidence and uncertainty",roles:ROLES,reply:"Assessment: separate allegations from proof, and do not assume the final outcome from incomplete facts."}]
];
export function initialSession(role="defendant"){if(!ROLES.includes(role))throw Error("Unknown role");return {version:1,role,stage:0,events:[],completed:false};}
export function allowedActions(session){return OPTIONS[session.stage].filter(action=>action.roles.includes(session.role));}
export function applyAction(session,id){if(session.completed)throw Error("Session is complete");const action=allowedActions(session).find(x=>x.id===id);if(!action)throw Error("Action not permitted for this role and stage");const event={seq:session.events.length+1,stage:STAGES[session.stage],role:session.role,action:id,text:action.reply};const next={...session,events:[...session.events,event],stage:Math.min(session.stage+1,STAGES.length-1),completed:session.stage===STAGES.length-1};return {session:next,event};}
const KEY="court-simulator-prototype-v1";
function restore(){try{const s=JSON.parse(localStorage.getItem(KEY));if(!s||s.version!==1||!ROLES.includes(s.role)||!Number.isInteger(s.stage)||s.stage<0||s.stage>=STAGES.length||!Array.isArray(s.events)||typeof s.completed!=="boolean")return initialSession();return s}catch{return initialSession()}}
function save(s){localStorage.setItem(KEY,JSON.stringify(s));}
function exportSession(session){const blob=new Blob([JSON.stringify({disclaimer:"Fictional educational simulation",...session},null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download="court-training-session.json";link.click();URL.revokeObjectURL(url);}
if(typeof document!=="undefined"){let session=restore();const el=id=>document.getElementById(id);const scenes=["Case intake: read the allegations and identify the question in dispute.","Pleadings: the two sides explain what they claim and what they dispute.","Evidence: identify documents and distinguish their existence from what they prove.","Hearing: practice objections, judicial questions, testimony, and accurate recordkeeping.","Conclusion: reflect on the arguments, missing information, and procedural fairness."];function render(){el("role").value=session.role;el("stageLabel").textContent=session.completed?"Completed":STAGES[session.stage];el("progressLabel").textContent="Stage "+(session.stage+1)+" of "+STAGES.length;el("actorBadge").textContent=session.role.replaceAll("_"," ");el("scene").textContent=session.completed?"Practice session completed. Review or export the transcript, or reset to practice again.":scenes[session.stage];el("promptTitle").textContent=session.completed?"Session complete":"What will you do next?";el("timeline").replaceChildren(...STAGES.map((stage,i)=>{const li=document.createElement("li");li.textContent=stage;li.className=i===session.stage?"current":i<session.stage?"done":"";return li}));const buttons=allowedActions(session).map(action=>{const b=document.createElement("button");b.className="action";b.textContent=action.label;b.disabled=session.completed;b.addEventListener("click",()=>{try{const result=applyAction(session,action.id);session=result.session;save(session);render();el("feedback").textContent=result.event.text}catch(e){el("feedback").textContent=e.message}});return b});el("actions").replaceChildren(...buttons);el("transcript").replaceChildren(...session.events.map(ev=>{const li=document.createElement("li");const strong=document.createElement("strong");strong.textContent=ev.role.replaceAll("_"," ")+": ";li.append(strong,document.createTextNode(ev.text));return li}));}el("role").addEventListener("change",e=>{session=initialSession(e.target.value);save(session);el("feedback").textContent="Started a new session for this role.";render()});el("resetBtn").addEventListener("click",()=>{session=initialSession(session.role);save(session);el("feedback").textContent="Session reset.";render()});el("exportBtn").addEventListener("click",()=>exportSession(session));document.querySelectorAll("[data-document]").forEach(b=>b.addEventListener("click",()=>{el("exhibitViewer").textContent=EXHIBITS[b.dataset.document]}));render();}
